namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateTime(2026, 5, 10)),
            new(2, "Conveyor Belt B",   "Warehouse 2",  new DateTime(2026, 4, 22)),
            new(3, "Pallet Jack C",     "Loading Dock",  new DateTime(2026, 6, 1)),
            new(4, "Crane D",           "Yard North",    new DateTime(2026, 3, 15)),
            new(5, "Hydraulic Press E", "Shop Floor",    new DateTime(2026, 6, 12)),
            new(6, "Generator F",       "Utility Room",  new DateTime(2026, 2, 28)),
            new(7, "Compressor G",      "Maintenance",   new DateTime(2026, 5, 5)),
            new(8, "Drill Press H",     "Shop Floor",    new DateTime(2026, 1, 19)),
        };
    }
}

@page "/inventory"
@using InventoryApp.Services
@inject EquipmentService Equipment

@attribute [StreamRendering]
@rendermode InteractiveServer

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? items;

    protected override async Task OnInitializedAsync()
    {
        items = await Equipment.GetEquipmentAsync();
    }
}

